using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Conquest.WorldMap;
public static class BuildCampaignForestMasses {
 [Serializable]public class Record{public string id,guid;}
 [Serializable]public class Baseline{public Record[] sectors;}
 const string Folder="Assets/WorldMap/Campaign/ForestMasses",BaselineFile="Docs/ForestMassBaseline.json";
 static void EnsureFolder(string path){if(AssetDatabase.IsValidFolder(path))return;var parent=Path.GetDirectoryName(path).Replace('\\','/');EnsureFolder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(path));}
 public static string Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");var c=UnityEngine.Object.FindAnyObjectByType<WorldMapCampaignController>();if(c.gameObject.scene.isDirty)throw new Exception("Save scene first");EnsureFolder(Folder);
  var profile=AssetDatabase.LoadAssetAtPath<WorldMapForestMassProfile>(Folder+"/Profile.asset");if(!profile){profile=ScriptableObject.CreateInstance<WorldMapForestMassProfile>();AssetDatabase.CreateAsset(profile,Folder+"/Profile.asset");}
  Baseline baseline;if(File.Exists(BaselineFile))baseline=JsonUtility.FromJson<Baseline>(File.ReadAllText(BaselineFile));else{baseline=new Baseline{sectors=c.streamer.manifest.sectors.Select(s=>{var asset=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/WorldMap/Campaign/Sectors/"+s.id+".prefab");return new Record{id=s.id,guid=AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(asset.GetComponent<WorldMapCampaignSector>().terrain.terrainData))};}).ToArray()};File.WriteAllText(BaselineFile,JsonUtility.ToJson(baseline,true));}
  var density=new Dictionary<Vector2Int,int>();var sourceScene=EditorSceneManager.OpenScene("Assets/Scenes/WorldMapTools/Experiments/StrategicTrials/StrategicTrials.unity",OpenSceneMode.Additive);
  try{var lab=sourceScene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<WorldMapScaleLab>(true)).First();foreach(var f in lab.forests){var data=f.native;var origin=f.terrain.transform.position;foreach(var t in data.treeInstances){var p=origin+Vector3.Scale(t.position,data.size);var key=new Vector2Int(Mathf.FloorToInt(p.x/50),Mathf.FloorToInt(p.z/50));density.TryGetValue(key,out var n);density[key]=n+1;}}}finally{EditorSceneManager.CloseScene(sourceScene,true);}
  int total=0,dense=0,edges=0,changedThin=0;float sumDiameter=0;foreach(var s in c.streamer.manifest.sectors){var old=AssetDatabase.LoadAssetAtPath<TerrainData>(AssetDatabase.GUIDToAssetPath(baseline.sectors.Single(r=>r.id==s.id).guid));var trees=old.treeInstances;var size=old.size;var prototypeBounds=old.treePrototypes.Select(p=>{var renderers=p.prefab.GetComponentsInChildren<Renderer>(true);var b=renderers[0].bounds;foreach(var r in renderers.Skip(1))b.Encapsulate(r.bounds);return b.size;}).ToArray();
   for(int i=0;i<trees.Length;i++){var t=trees[i];var p=s.origin+Vector3.Scale(t.position,size);var key=new Vector2Int(Mathf.FloorToInt(p.x/50),Mathf.FloorToInt(p.z/50));int occupied=0,count=0;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)if(density.TryGetValue(key+new Vector2Int(x,z),out var n)){occupied++;count+=n;}
    float concentration=Mathf.Clamp01(occupied/9f)*.6f+Mathf.Clamp01(count/28f)*.4f;float noise=Mathf.PerlinNoise((p.x+profile.seed*73)/profile.canopyNoiseScale,p.z/profile.canopyNoiseScale);float diameter=Mathf.Lerp(profile.edgeDiameter,profile.denseDiameter,Mathf.SmoothStep(0,1,concentration))*(1+(noise-.5f)*2*profile.diameterVariation);float height=Mathf.Lerp(profile.edgeHeight,profile.denseHeight,concentration)*(1+(noise-.5f)*.2f);
    if(t.prototypeIndex==3||t.prototypeIndex==4){t.prototypeIndex=(int)((uint)(key.x*73856093^key.y*19349663^profile.seed)%3);changedThin++;}
    // Keep enlarged crowns away from water and around the existing fixture clearings.
    if(c.navigation){for(int a=0;a<8;a++){float angle=a*Mathf.PI*.25f;var edge=p+new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*diameter*.45f;int index=c.navigation.Index(edge);if(index>=0&&(c.navigation.blocked[index]==1||c.navigation.blocked[index]==3))diameter=Mathf.Min(diameter,profile.edgeDiameter);}}
    foreach(var city in new[]{c.cityA,c.cityB}){float d=Vector2.Distance(new Vector2(p.x,p.z),new Vector2(city.position.x,city.position.z));if(d<180)diameter=Mathf.Min(diameter,Mathf.Max(18,(d-110)*2));}
    var bounds=prototypeBounds[t.prototypeIndex];t.widthScale=diameter/Mathf.Max(bounds.x,bounds.z);t.heightScale=height/Mathf.Max(.01f,bounds.y);float shade=Mathf.Lerp(.85f,1.04f,Mathf.PerlinNoise((p.x+181)/profile.shadeScale,(p.z+profile.seed*47)/profile.shadeScale));t.color=new Color(t.color.r*shade,t.color.g*shade,t.color.b*shade,1);trees[i]=t;sumDiameter+=diameter;if(concentration>.75f)dense++;if(concentration<.45f)edges++;
   }
   var clone=UnityEngine.Object.Instantiate(old);clone.name=s.id+" forest masses";var ground=AssetDatabase.LoadAssetAtPath<TerrainData>("Assets/Scenes/WorldMapTools/Experiments/MountainsV9/"+s.id+".asset");if(!ground)throw new Exception("Missing accepted ground: "+s.id);clone.terrainLayers=ground.terrainLayers;clone.alphamapResolution=ground.alphamapResolution;clone.SetAlphamaps(0,0,ground.GetAlphamaps(0,0,ground.alphamapWidth,ground.alphamapHeight));clone.SetTreeInstances(trees,false);string dataPath=Folder+"/"+s.id+".asset";var existing=AssetDatabase.LoadAssetAtPath<TerrainData>(dataPath);if(existing){EditorUtility.CopySerialized(clone,existing);UnityEngine.Object.DestroyImmediate(clone);clone=existing;}else AssetDatabase.CreateAsset(clone,dataPath);clone.terrainLayers=ground.terrainLayers;clone.SetAlphamaps(0,0,ground.GetAlphamaps(0,0,ground.alphamapWidth,ground.alphamapHeight));clone.SetBaseMapDirty();foreach(var splat in clone.alphamapTextures)EditorUtility.SetDirty(splat);EditorUtility.SetDirty(clone);var root=PrefabUtility.LoadPrefabContents("Assets/WorldMap/Campaign/Sectors/"+s.id+".prefab");try{var sector=root.GetComponent<WorldMapCampaignSector>();sector.terrain.terrainData=clone;root.GetComponentInChildren<TerrainCollider>().terrainData=clone;PrefabUtility.SaveAsPrefabAsset(root,"Assets/WorldMap/Campaign/Sectors/"+s.id+".prefab");}finally{PrefabUtility.UnloadPrefabContents(root);}total+=trees.Length;
  }
  if(!string.IsNullOrEmpty(c.streamer.manifest.coastRevision))Conquest.WorldMap.Editor.WorldMapCampaignCoastBuilder.Build(c.streamer.manifest.sourcePackage);
  AssetDatabase.SaveAssets();string report=$"Forest mass representation: {total} crowns unchanged; dense interiors={dense}; open edges={edges}; thin prototypes replaced={changedThin}; average diameter={sumDiameter/total:F1}u. Original terrain assets preserved; no positions, heights, resources or economic forest mask changed.";File.WriteAllText("Docs/ForestMassBuild.txt",report);return report;
 }
}
